const item = $input.first();
const body = item.json.body || item.json;
const userId = (body.userId || body.userid || '').toString().trim();

if (!userId) {
  return [{ json: { error: true, statusCode: 400, message: 'شناسه کاربر الزامی است' } }];
}

const binaryKey = item.binary?.image ? 'image' : (item.binary?.data ? 'data' : null);
if (!binaryKey) {
  return [{ json: { error: true, statusCode: 400, message: 'فایل تصویر ارسال نشده است' } }];
}

return [{
  json: { error: false, userId, binaryKey },
  binary: item.binary
}];

const raw = $input.first().json;

function extractTextFromParts(parts) {
  if (!Array.isArray(parts)) return '';
  const withText = parts.find((p) => typeof p.text === 'string' && p.text.trim());
  return withText?.text || '';
}

let text = '';

if (Array.isArray(raw.candidates) && raw.candidates.length) {
  text = extractTextFromParts(raw.candidates[0]?.content?.parts);
}
if (!text && raw.content?.parts?.length) {
  text = extractTextFromParts(raw.content.parts);
}
if (!text && typeof raw.text === 'string') text = raw.text;
if (!text && typeof raw.output === 'string') text = raw.output;

const cleaned = text.replace(/```json\s*|```/gi, '').trim();
let parsed = {};

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      error: true,
      statusCode: 422,
      message: 'پاسخ Gemini قابل خواندن نیست',
      rawText: text
    }
  }];
}

return [{ json: { error: false, ...parsed } }];

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

const input = $input.first().json;

if (input.error) {
  return [{ json: input }];
}

const userId = $('Validate Input').first().json.userId;
let bloodSugar = Number(input.bloodSugar ?? input.blood_sugar);
const unit = (input.unit || 'mg/dL').toString();

if (unit.toLowerCase() === 'mmol/l' && !isNaN(bloodSugar)) {
  bloodSugar = Math.round(bloodSugar * 18.0182);
}

if (!bloodSugar || isNaN(bloodSugar) || bloodSugar <= 0 || bloodSugar > 600) {
  return [{
    json: {
      error: true,
      statusCode: 422,
      message: input.notes || 'عدد قند خون از عکس قابل تشخیص نبود. عکس واضح‌تری بگیرید.'
    }
  }];
}

const TZ = 'Asia/Dubai';
const now = new Date();
const confidence = input.confidence || 'unknown';
const notes = input.notes || `خوانده‌شده توسط Gemini (${confidence})`;

return [{
  json: {
    error: false,
    recordId: generateUUID(),
    userId,
    Date: now.toLocaleDateString('fa-IR', { timeZone: TZ }),
    Time: now.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', timeZone: TZ }),
    BloodSugar: Math.round(bloodSugar),
    Notes: notes,
    createdAt: now.toISOString()
  }
}];
